package org.peirs.config;
import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*; import java.util.List; import org.peirs.security.JwtAuthFilter;
@Configuration public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain filter(HttpSecurity http,JwtAuthFilter jwt)throws Exception{return http.csrf(c->c.disable()).cors(c->c.configurationSource(r->{var x=new CorsConfiguration();x.setAllowedOriginPatterns(List.of("*"));x.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));x.setAllowedHeaders(List.of("*"));return x;})).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).authorizeHttpRequests(a->a.requestMatchers("/api/auth/login","/api/auth/register","/v3/api-docs/**","/swagger-ui/**","/swagger-ui.html","/actuator/health").permitAll().requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/settings/**").hasRole("ADMIN").requestMatchers("/api/optimization").hasAnyRole("ADMIN","INVESTMENT_MANAGER").requestMatchers("/api/projects/*/evaluations","/api/evaluations").hasAnyRole("ADMIN","EVALUATOR").anyRequest().authenticated()).build();} }
